<template id="item-template"><div class="item-row grid grid-cols-12 gap-3 items-end bg-slate-50 p-4 rounded-xl border"><div class="col-span-5"><label>Produk</label><select name="items[__INDEX__][product_id]" required class="w-full rounded-xl border p-3" onchange="updatePrice(this)"><option value="">Pilih Produk</option>@foreach($products as $product)<option value="{{ $product->id }}" data-price="{{ $product->buy_price }}">{{ $product->name }} (Harga Beli: Rp {{ number_format($product->buy_price,0,',','.') }})</option>@endforeach</select></div><div class="col-span-2"><label>Qty</label><input type="number" name="items[__INDEX__][quantity]" value="1" min="1" required class="w-full rounded-xl border p-3"></div><div class="col-span-3"><label>Harga Beli</label><input type="number" name="items[__INDEX__][price]" value="0" min="0" required class="price-input w-full rounded-xl border p-3"></div><div class="col-span-2"><button type="button" onclick="removeItem(this)" class="w-full px-3 py-3 bg-red-50 text-red-600 rounded-xl">Hapus</button></div></div></template>
<script>let itemIndex={{ $bill->items->count() }};function addItem(){let t=document.getElementById('item-template').innerHTML.replaceAll('__INDEX__',itemIndex++);document.getElementById('items-container').insertAdjacentHTML('beforeend',t)}function removeItem(b){b.closest('.item-row').remove();if(!document.querySelector('.item-row'))addItem()}function updatePrice(s){s.closest('.item-row').querySelector('.price-input').value=s.options[s.selectedIndex].dataset.price||0}</script>
